<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {uiErrorMessage} from '@kuaixie/i18n';
import {createAdminApi} from '../api/client';
interface Field {table:string;column:string;description:string;usage:string;origin:string;domain:string;frontendIntent:string;adminIntent:string;sqlCandidates:string[];status:string}
interface Coverage {tableCount:number;suppliedTableCount:number;fieldCount:number;unverifiedFieldCount:number;domains:{id:string;title:string}[];fields:Field[]}
const data=ref<Coverage|null>(null),error=ref(''),busy=ref(false),search=ref(''),domain=ref('');
const filtered=computed(()=>(data.value?.fields||[]).filter(row=>(!domain.value||domain.value===row.domain)&&(!search.value||(row.table+'.'+row.column).includes(search.value.trim()))));
async function load(){busy.value=true;error.value='';try{data.value=await createAdminApi().request<Coverage>('GET','/portal/admin/business-coverage')}catch(e){error.value=uiErrorMessage(e)}finally{busy.value=false}}
onMounted(()=>{void load()});
</script>
<template><section class="coverage-panel"><h2>{{$t('coverage.title')}}</h2><p>{{$t('coverage.help')}}</p><button :disabled="busy" @click="load">{{$t('common.retry')}}</button><p v-if="error" role="alert">{{error}}</p><template v-if="data"><div class="coverage-summary"><strong>{{$t('coverage.tables')}} {{data.tableCount}}</strong><strong>{{$t('coverage.fields')}} {{data.fieldCount}}</strong><strong>{{$t('coverage.pending')}} {{data.unverifiedFieldCount}}</strong></div><div class="coverage-filters"><input v-model="search" :placeholder="$t('coverage.search')"/><select v-model="domain"><option value="">{{$t('common.all')}}</option><option v-for="item in data.domains" :key="item.id" :value="item.id">{{item.title}}</option></select></div><p>{{$t('coverage.intentNotice')}}</p><div class="coverage-scroll"><table><thead><tr><th>{{$t('coverage.table')}}</th><th>{{$t('coverage.field')}}</th><th>{{$t('coverage.frontend')}}</th><th>{{$t('coverage.admin')}}</th><th>{{$t('coverage.status')}}</th><th>{{$t('coverage.evidence')}}</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.table+'.'+row.column"><td>{{row.table}}<small v-if="row.origin==='proposed'">{{$t('coverage.proposed')}}</small></td><td>{{row.column}}<p>{{row.description}}</p><small>{{row.usage}}</small></td><td>{{row.frontendIntent}}</td><td>{{row.adminIntent}}</td><td>{{$t(row.status==='verified'?'coverage.verified':'coverage.pending')}}</td><td><details><summary>{{row.sqlCandidates.length}}</summary><p v-for="file in row.sqlCandidates" :key="file">{{file}}</p></details></td></tr></tbody></table></div></template></section></template>
<style scoped>.coverage-panel{padding:24px;background:var(--kx-surface,#fff);border:1px solid #e2e8f0;border-radius:18px}.coverage-summary,.coverage-filters{display:flex;flex-wrap:wrap;gap:20px;margin:20px 0}.coverage-panel p{font-size:13px;line-height:1.7}.coverage-filters input,.coverage-filters select{padding:10px;border:1px solid #cbd5e1;border-radius:9px}.coverage-scroll{overflow:auto;max-height:70vh}.coverage-panel table{border-collapse:collapse;min-width:1000px;width:100%;font-size:12px}.coverage-panel th,.coverage-panel td{padding:10px;text-align:left;border:1px solid #e2e8f0;vertical-align:top}.coverage-panel th{position:sticky;top:0;background:#f1f5f9;color:#0f172a}.coverage-panel small{display:block;color:#b45309}.coverage-panel button{padding:10px 16px;border:0;background:#0e7490;color:white;border-radius:8px}</style>
